output_text:
[
  {
    "id": "must_take_entrance_cart",
    "text": "Customers are obliged to take the entrance cart before completing the shopping trip.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "has_shopping_cart": "hasCart"
      },
      "events": {
        "pickup_entrance_cart": {
          "pre": {
            "and": [
              "entrance_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "has_shopping_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "pickup_entrance_cart"
    }
  },
  {
    "id": "no_hand_carrying_items",
    "text": "Items may not be taken or carried by hand; they must be collected only while the customer has a cart.",
    "abstraction": {
      "state_properties": {
        "hand_carrying_item": "handFull",
        "has_shopping_cart": "hasCart"
      },
      "events": {
        "item_pickup_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "has_shopping_cart"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "hand_carrying_item",
          "item_pickup_without_cart"
        ]
      }
    }
  },
  {
    "id": "items_trigger_cart_return",
    "text": "After putting any item into a cart, the customer is obliged to return that cart to the front return bay before exiting.",
    "abstraction": {
      "state_properties": {
        "has_shopping_cart": "hasCart",
        "front_return_bay": "at(0,1)",
        "cart_parked_front": "cartAt(0,1)"
      },
      "events": {
        "item_put_in_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "has_shopping_cart"
            ]
          },
          "post": null
        },
        "return_cart_front": {
          "pre": {
            "and": [
              "front_return_bay",
              "has_shopping_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_front"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "item_put_in_cart",
      "discharge": "return_cart_front"
    }
  },
  {
    "id": "cart_only_left_at_front",
    "text": "A cart may be put down only at the designated front return bay.",
    "abstraction": {
      "state_properties": {
        "front_return_bay": "at(0,1)"
      },
      "events": {
        "leave_cart_elsewhere": {
          "pre": {
            "and": [
              "LEAVE_CART",
              {
                "not": "front_return_bay"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_elsewhere"
    }
  },
  {
    "id": "exit_requires_cart_returned",
    "text": "Customers are forbidden to exit unless their cart has already been parked in the front return bay.",
    "abstraction": {
      "state_properties": {
        "cart_returned_front": "cartAt(0,1)"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "cart_returned_front"
          }
        ]
      }
    }
  },
  {
    "id": "no_carts_in_exit_corridor",
    "text": "Shopping carts are not allowed in the exit corridor near the checkout exit.",
    "abstraction": {
      "state_properties": {
        "has_shopping_cart": "hasCart",
        "exit_corridor": {
          "or": [
            "at(7,5)",
            "at(8,5)",
            "at(9,5)"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "has_shopping_cart",
          "exit_corridor"
        ]
      }
    }
  },
  {
    "id": "no_interactions_after_cart_return",
    "text": "Once the cart has been returned to the front bay, the customer must not perform any further store interactions.",
    "abstraction": {
      "state_properties": {
        "cart_returned_front": "cartAt(0,1)"
      },
      "events": {
        "post_return_interaction": {
          "pre": {
            "and": [
              "cart_returned_front",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "post_return_interaction"
    }
  },
  {
    "id": "must_drop_cart_when_at_return_bay",
    "text": "A customer who reaches the front return bay while still holding a cart may not move on until the cart is left there.",
    "abstraction": {
      "state_properties": {
        "front_return_bay": "at(0,1)",
        "has_shopping_cart": "hasCart"
      },
      "events": {
        "move_away_with_cart_from_return_bay": {
          "pre": {
            "and": [
              "front_return_bay",
              "has_shopping_cart",
              "MOVE"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "move_away_with_cart_from_return_bay"
    }
  }
]
